import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from zeitfenster import normalisiere_zeitfenster


class ZeitfensterTest(unittest.TestCase):
    def test_gueltiges_fenster(self):
        self.assertEqual(normalisiere_zeitfenster("09:05-10:30"), (545, 630))

    def test_grenzen(self):
        self.assertEqual(normalisiere_zeitfenster("00:00-23:59"), (0, 1439))

    def test_ungueltige_eingaben(self):
        for raw in ("", "9:00-10:00", "24:00-25:00", "10:60-11:00",
                    "10:00-10:00", "11:00-10:00", "Text"):
            with self.subTest(raw=raw):
                with self.assertRaises(ValueError):
                    normalisiere_zeitfenster(raw)


if __name__ == "__main__":
    unittest.main()

