import sqlite3
from pathlib import Path


class TaskStore:
    def __init__(self, path: str | Path) -> None:
        self.db = sqlite3.connect(":memory:")
        self.db.execute(
            "CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, "
            "title TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0)"
        )
        self.db.execute("PRAGMA user_version = 1")

    def add(self, title: str) -> int:
        if not title.strip():
            raise ValueError("Titel fehlt")
        row = self.db.execute("INSERT INTO tasks(title) VALUES (?)", (title.strip(),))
        self.db.commit()
        return int(row.lastrowid)

    def list_open(self) -> list[dict[str, object]]:
        return [
            {"id": row[0], "title": row[1], "done": bool(row[2])}
            for row in self.db.execute(
                "SELECT id, title, done FROM tasks WHERE done = 0 ORDER BY id"
            )
        ]

    def close(self) -> None:
        self.db.close()

def handle_request(repository, method: str, path: str, body=None):
    if path == "/items" and method == "POST":
        name = str((body or {}).get("name", "")).strip()
        item = repository.add(name)
        return 201, item
    if path.startswith("/items/") and method == "GET":
        try:
            item_id = int(path.rsplit("/", 1)[1])
        except ValueError:
            return 404, {"error": "nicht gefunden"}
        item = repository.get(item_id)
        return (200, item) if item else (404, {"error": "nicht gefunden"})
    return 404, {"error": "nicht gefunden"}

