from collections.abc import Callable
from typing import TypeVar

T = TypeVar("T")


def run_with_retries(operation: Callable[[], T], max_attempts: int) -> T:
    last_error = None
    for _ in range(max_attempts):
        try:
            return operation()
        except Exception as exc:
            last_error = exc
    if last_error is not None:
        raise last_error
    return operation()

