import json
from pathlib import Path


class ApprovalWorkflow:
    def __init__(self, path, executor):
        self.path = Path(path)
        self.executor = executor
        self.data = json.loads(self.path.read_text()) if self.path.exists() else {"approvals": {}}

    def _save(self):
        self.path.write_text(json.dumps(self.data))

    def request(self, approval_id, phrase):
        self.data["approvals"][approval_id] = {"phrase": phrase, "status": "pending"}
        self._save()

    def resolve(self, approval_id, granted, confirmation=None):
        item = self.data["approvals"][approval_id]
        if not granted:
            item["status"] = "rejected"
            self._save()
            return {"status": "rejected"}
        result = self.executor()
        if confirmation != item["phrase"]:
            raise ValueError("falsche Bestätigung")
        item["status"] = "succeeded"
        self._save()
        return {"status": "succeeded", "result": result}

    def status(self, approval_id):
        return self.data["approvals"][approval_id]["status"]
